test('Page Builder bulk property engine enforces selection-wide edits and metadata contracts',async()=>{
 const {isSharedCanvasProperty,mixedCanvasPropertyIds,updateSharedCanvasProperties,
   updateSharedCanvasPositions}=await import('../src/core/builders/PageBuilder/canvasSharedRibbonProperties.ts');
 const create=(id,api,properties={},parentId=null)=>({
   id,type:'Custom:'+api,label:id,region:'main',visible:true,parentId,properties,
   position:{x:0,y:0,width:200,height:48}
 });
 const primary=create('primary','smart_text',{borderColor:'#f60',textSize:16});
 const secondary=create('secondary','smart_label',{borderColor:'#059',textSize:12});
 secondary.position.width=160;
 const outsider=create('outsider','smart_text',{borderColor:'#333',textSize:99});
 const meta=[
   {id:'borderColor',label:'Border colour',tab:'Design',group:'Body',
    kind:'color',components:['smart_text','smart_label']},
   {id:'textSize',label:'Size',tab:'Design2',group:'Body',
    kind:'number',components:['smart_text','smart_label']},
   {id:'width',label:'Width',tab:'Layout',group:'Size',
    kind:'position',components:['smart_text','smart_label']}
 ];
 const selected=[primary,secondary],all=[...selected,outsider];
 assert.equal(isSharedCanvasProperty(meta[0],selected,meta),true);
 assert.ok(mixedCanvasPropertyIds(meta,'Design',selected).includes('borderColor'));
 // Reapplying primary's existing value must update ALL selected children.
 const recolored=updateSharedCanvasProperties(all,primary.id,selected,meta,'Design',
   {...primary.properties,borderColor:'#f60'},['borderColor']);
 assert.deepEqual(recolored.map(c=>c.properties.borderColor),['#f60','#f60','#333']);
 assert.equal(recolored[1].properties.textSize,12,'unrelated mixed property remains intact');
 const resized=updateSharedCanvasPositions(all,primary.id,selected,meta,
   {...primary.position,width:200},['width']);
 assert.deepEqual(resized.map(c=>c.position.width),[200,200,200]);
 // 50 selected components use the same update path, not the primary's ID.
 const large=Array.from({length:50},(_,i)=>create('component-'+i,
   i%2?'smart_label':'smart_text',{borderColor:i?'#123':'#f60'}));
 const changed=updateSharedCanvasProperties(large,large[0].id,large,meta,'Design',
   {...large[0].properties,borderColor:'#f60'},['borderColor']);
 assert.ok(changed.every(c=>c.properties.borderColor==='#f60'));
 const locked=create('locked','smart_label',{editorLocked:true,borderColor:'#123'});
 assert.equal(isSharedCanvasProperty(meta[0],[primary,locked],meta),false);
 const nested=create('nested','smart_label',{borderColor:'#123'},'different-parent');
 assert.equal(isSharedCanvasProperty(meta[0],[primary,nested],meta),false);
 const conditional={
   id:'labelColor',label:'Text',tab:'Design',group:'Body',kind:'color',
   components:['smart_text','smart_label'],
   enabledWhen:{property:'displayMode',in:['display']}
 };
 const mode={id:'displayMode',label:'Mode',tab:'Design',group:'Body',kind:'choice',
   components:['smart_text','smart_label'],default:'display',choices:['display','input']};
 assert.equal(isSharedCanvasProperty(conditional,[primary,secondary],[conditional,mode]),true);
 assert.equal(isSharedCanvasProperty(conditional,[primary,create('input','smart_label',
   {displayMode:'input'})],[conditional,mode]),false);
 const allowed={id:'imageFill',label:'Fill',tab:'Design',group:'Body',kind:'choice',
   components:['smart_text','smart_label'],choices:['cover','contain','stretch'],
   choicesOverrides:{smart_text:['cover','stretch'],smart_label:['cover']}};
 assert.equal(isSharedCanvasProperty(allowed,selected,[allowed]),true);
 const valid=updateSharedCanvasProperties(all,primary.id,selected,[allowed],'Design',
   {...primary.properties,imageFill:'cover'},['imageFill']);
 assert.equal(valid[1].properties.imageFill,'cover');
 const invalid=updateSharedCanvasProperties(all,primary.id,selected,[allowed],'Design',
   {...primary.properties,imageFill:'stretch'},['imageFill']);
 assert.ok(invalid.every(item=>item.properties.imageFill===undefined));
 const incompatible={...allowed,choicesOverrides:{smart_text:['stretch'],smart_label:['cover']}};
 assert.equal(isSharedCanvasProperty(incompatible,selected,[incompatible]),false);
 const differentKind={...meta[0],kindOverrides:{smart_label:'number'}};
 assert.equal(isSharedCanvasProperty(differentKind,selected,[differentKind]),false);
});

